begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','get_asset_version_review_state',array['uuid'],'Authoritative mutation state is independent of display pagination');
create function pg_temp.uid(k integer,n integer) returns uuid language sql immutable as $$select ('a5180000-'||lpad(k::text,4,'0')||'-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email) values(pg_temp.uid(1,1),'draft.operator@pln.co.id'),(pg_temp.uid(1,2),'draft.reviewer@pln.co.id'),(pg_temp.uid(1,3),'draft.admin@pln.co.id');
update public.profiles set status='ACTIVE' where id in(pg_temp.uid(1,1),pg_temp.uid(1,2),pg_temp.uid(1,3));
insert into public.user_role_assignments(user_id,role) values(pg_temp.uid(1,1),'UNIT_OPERATOR'),(pg_temp.uid(1,2),'RST_REVIEWER'),(pg_temp.uid(1,3),'RST_ADMIN');
insert into public.unit_induk(id,code,name) values(pg_temp.uid(2,1),'DRAFT_REVIEW_A','Synthetic draft unit A'),(pg_temp.uid(2,2),'DRAFT_REVIEW_B','Synthetic draft unit B');
insert into public.datasets(id,unit_induk_id,type) values(pg_temp.uid(3,1),pg_temp.uid(2,1),'ASSET'),(pg_temp.uid(3,2),pg_temp.uid(2,2),'ASSET');
insert into public.dataset_versions(id,dataset_id,version_number,status) select pg_temp.uid(4,n),pg_temp.uid(3,case when n=7 then 2 else 1 end),n,case n when 1 then 'HISTORICAL'::public.dataset_status when 5 then 'PENDING_RST'::public.dataset_status when 6 then 'ACTIVE'::public.dataset_status else 'DRAFT'::public.dataset_status end from generate_series(1,7)n;
update public.datasets set active_version_id=pg_temp.uid(4,6) where id=pg_temp.uid(3,1);
insert into public.source_files(id,unit_induk_id,object_path,original_name,byte_size,sha256,uploaded_by) select pg_temp.uid(5,n),pg_temp.uid(2,case when n=7 then 2 else 1 end),'unit/'||pg_temp.uid(2,case when n=7 then 2 else 1 end)||'/dataset/'||pg_temp.uid(3,case when n=7 then 2 else 1 end)||'/version/'||pg_temp.uid(4,n)||'/'||pg_temp.uid(5,n)||'.xlsx','synthetic-draft.xlsx',1,repeat(case when n=3 then 'b' else 'a' end,64),pg_temp.uid(1,1) from generate_series(1,7)n;
insert into public.import_sessions(id,unit_induk_id,dataset_id,dataset_version_id,source_file_id,created_by) select pg_temp.uid(6,n),pg_temp.uid(2,case when n=7 then 2 else 1 end),pg_temp.uid(3,case when n=7 then 2 else 1 end),pg_temp.uid(4,n),pg_temp.uid(5,n),pg_temp.uid(1,1) from generate_series(1,7)n;
insert into public.approval_events(dataset_version_id,actor_id,action,notes) values(pg_temp.uid(4,4),pg_temp.uid(1,2),'APPROVED','Synthetic referenced evidence');
create function pg_temp.expected(n integer) returns jsonb language sql as $$select jsonb_build_object('kind','UNPROCESSED_DRAFT','unitId',s.unit_induk_id,'sourceFileId',s.source_file_id,'mappingRevision',s.mapping_revision,'updatedAt',v.updated_at) from public.import_sessions s join public.dataset_versions v on v.id=s.dataset_version_id where v.id=pg_temp.uid(4,n)$$;
create function pg_temp.trash(n integer,actor_n integer default 3,token jsonb default null,note text default 'Duplicate source digest verified') returns jsonb language sql as $$select public.review_asset_version(pg_temp.uid(1,actor_n),pg_temp.uid(4,n),'TRASH',coalesce(token,pg_temp.expected(n)),note,'{}','{"offset":0,"filter":"ALL"}',false)$$;
select lives_ok($$select public.get_asset_version_review_state(pg_temp.uid(4,2))$$,'Unprocessed duplicate can load real review state');
select throws_ok($$select pg_temp.trash(2,2)$$,'42501',null,'Reviewer cannot trash unprocessed duplicate');
select throws_ok($$select pg_temp.trash(2,1)$$,'42501',null,'Operator cannot use draft-trash service RPC');
select throws_ok($$select pg_temp.trash(3)$$,'22023',null,'A unique nonduplicate draft is not eligible');
select throws_ok($$select pg_temp.trash(4)$$,'22023',null,'Approval-referenced draft cannot be trashed');
select throws_ok($$select pg_temp.trash(5)$$,'22023',null,'Pending draft-shaped state cannot be trashed');
select throws_ok($$select pg_temp.trash(6)$$,'22023',null,'Active draft-shaped state cannot be trashed');
select throws_ok($$select pg_temp.trash(7,3,jsonb_set(pg_temp.expected(7),'{unitId}',to_jsonb(pg_temp.uid(2,1))))$$,'42501',null,'Wrong expected unit cannot target another unit draft');
select throws_ok($$select pg_temp.trash(2,3,jsonb_set(pg_temp.expected(2),'{updatedAt}','"2000-01-01T00:00:00Z"'))$$,'22023',null,'Stale draft state is rejected');
select throws_ok($$select pg_temp.trash(2,3,null,' ')$$,'22023',null,'Draft trash requires note');
create function pg_temp.audit_failure() returns trigger language plpgsql as $$begin if new.target_id=pg_temp.uid(4,2) and new.action='ASSET_VERSION_TRASH' then raise exception 'Synthetic draft audit outage'; end if; return new; end$$;
create trigger synthetic_draft_audit before insert on public.audit_events for each row execute function pg_temp.audit_failure();
select throws_ok($$select pg_temp.trash(2)$$,'P0001',null,'Draft trash and audit are atomic');
select is((select status::text from public.dataset_versions where id=pg_temp.uid(4,2)),'DRAFT','Audit failure restores draft state');
drop trigger synthetic_draft_audit on public.audit_events;
select lives_ok($$select pg_temp.trash(2)$$,'Admin logically trashes duplicate without fabricated run tokens');
select is((select status::text from public.dataset_versions where id=pg_temp.uid(4,2)),'TRASH','Duplicate moved to logical trash');
select is((select count(*) from public.source_files where id=pg_temp.uid(5,2)),1::bigint,'Source object evidence metadata retained');
select is((select count(*) from public.audit_events where target_id=pg_temp.uid(4,2) and action='ASSET_VERSION_TRASH'),1::bigint,'Draft trash audit appended exactly once');
select is((select count(*) from public.approval_events where dataset_version_id=pg_temp.uid(4,2) and action='TRASHED'),1::bigint,'Logical trash approval appended exactly once');
select * from finish();
rollback;
